std::vector<Point2d> intersections;
const std::size_t n = segments.size();

for (std::size_t i = 0; i < n; ++i) {
    for (std::size_t j = i + 1; j < n; ++j) {
        const Segment2d& seg1 = segments[i];
        const Segment2d& seg2 = segments[j];

        // Compute orientation of triplet (p, q, r)
        auto orientation = [](const Point2d& p, const Point2d& q, const Point2d& r) {
            double val = (q.y - p.y) * (r.x - q.x) - (q.x - p.x) * (r.y - q.y);
            if (std::abs(val) < 1e-10) return 0;  // colinear
            return (val > 0) ? 1 : 2;             // clock or counterclock wise
        };

        // Check if point q lies on segment pr
        auto onSegment = [](const Point2d& p, const Point2d& q, const Point2d& r) {
            if (q.x <= std::max(p.x, r.x) && q.x >= std::min(p.x, r.x) &&
                q.y <= std::max(p.y, r.y) && q.y >= std::min(p.y, r.y)) {
                return true;
            }
            return false;
        };

        const Point2d& p1 = seg1.p1;
        const Point2d& q1 = seg1.p2;
        const Point2d& p2 = seg2.p1;
        const Point2d& q2 = seg2.p2;

        int o1 = orientation(p1, q1, p2);
        int o2 = orientation(p1, q1, q2);
        int o3 = orientation(p2, q2, p1);
        int o4 = orientation(p2, q2, q1);

        // General case
        if (o1 != o2 && o3 != o4) {
            // Compute intersection point
            double a1 = q1.y - p1.y;
            double b1 = p1.x - q1.x;
            double c1 = a1 * p1.x + b1 * p1.y;

            double a2 = q2.y - p2.y;
            double b2 = p2.x - q2.x;
            double c2 = a2 * p2.x + b2 * p2.y;

            double determinant = a1 * b2 - a2 * b1;

            if (std::abs(determinant) < 1e-10) {
                continue;  // parallel or colinear
            }

            double x = (b2 * c1 - b1 * c2) / determinant;
            double y = (a1 * c2 - a2 * c1) / determinant;

            intersections.emplace_back(x, y);
        }
        // Special cases (colinear)
        else if (o1 == 0 && onSegment(p1, p2, q1)) {
            intersections.push_back(p2);
        }
        else if (o2 == 0 && onSegment(p1, q2, q1)) {
            intersections.push_back(q2);
        }
        else if (o3 == 0 && onSegment(p2, p1, q2)) {
            intersections.push_back(p1);
        }
        else if (o4 == 0 && onSegment(p2, q1, q2)) {
            intersections.push_back(q1);
        }
    }
}

// Remove duplicates (using a set to avoid floating-point precision issues)
auto pointLess = [](const Point2d& a, const Point2d& b) {
    if (std::abs(a.x - b.x) > 1e-10) return a.x < b.x;
    return a.y < b.y;
};
std::set<Point2d, decltype(pointLess)> uniqueIntersections(intersections.begin(), intersections.end(), pointLess);
intersections.assign(uniqueIntersections.begin(), uniqueIntersections.end());

return intersections;
// END_CODE

